starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "asg_min" {
  description = "Input variable asg_min."
  type        = number
  default     = 1
}

variable "asg_max" {
  description = "Input variable asg_max."
  type        = number
  default     = 2
}

variable "asg_desired" {
  description = "Input variable asg_desired."
  type        = number
  default     = 1
}

variable "subnet_ids" {
  description = "Input variable subnet_ids."
  type        = list(string)
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_autoscaling_group" "this" {
